int contains(int a[], int n, int x) {
    int found = 0;
    for (int i = 0; i < n; i++) {
        if (a[i] == x) {
            found = 1;
        }
    }
    return found;
}

int contains(int a[], int n, int x) {
    int found = 0;
    int i = 0;
    while (i < n) {
        if (a[i] == x) {
            found = 1;
        }
        i++;
    }
    return found;
}

int contains(int a[], int n, int x) {
    int found = 0;
    int i;
    for (i = n - 1; i >= 0; i--) {
        if (a[i] == x) found = 1;
    }
    return found;
}
